-- 已发出的设备操作意图增加终态 settled。cancelled 仍只表示从未下发的 reserved。
DECLARE n INTEGER; BEGIN SELECT COUNT(*) INTO n FROM USER_CONSTRAINTS WHERE CONSTRAINT_NAME IN ('ck_device_intent_phase', 'CK_DEVICE_INTENT_PHASE') AND TABLE_NAME IN ('gb_device_operation_intent', 'GB_DEVICE_OPERATION_INTENT'); IF n > 0 THEN EXECUTE IMMEDIATE 'ALTER TABLE "gb_device_operation_intent" DROP CONSTRAINT "ck_device_intent_phase"'; END IF; EXECUTE IMMEDIATE 'ALTER TABLE "gb_device_operation_intent" ADD CONSTRAINT "ck_device_intent_phase" CHECK ((("updated_at" >= "created_at") and ((("state" = ''reserved'') and ("row_version" = 1) and ("dispatch_started_at" is null) and ("cancelled_at" is null)) or (("state" = ''dispatched'') and ("row_version" >= 2) and ("cancelled_at" is null) and ("dispatch_started_at" is not null) and ("dispatch_started_at" >= "created_at") and ("dispatch_started_at" <= "updated_at")) or (("state" = ''cancelled'') and ("row_version" >= 2) and ("dispatch_started_at" is null) and ("cancelled_at" is not null) and ("cancelled_at" >= "created_at") and ("cancelled_at" <= "updated_at")) or (("state" = ''settled'') and ("row_version" >= 3) and ("cancelled_at" is null) and ("dispatch_started_at" is not null) and ("dispatch_started_at" >= "created_at") and ("dispatch_started_at" <= "updated_at")))))'; END;
